<script setup>
import { computed, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { profile, projects, services, skills } from '../data/portfolio'
import { login, saveRemotePortfolio } from '../data/supabase'
import '../admin.css'
const credentials=reactive({email:'',password:''}),token=ref(localStorage.getItem('basga_token')||''),error=ref(''),saved=ref(false),section=ref('profile')
const sections=[['profile','Profil'],['projects','Proyek'],['skills','Keahlian'],['services','Layanan']]
const signIn=async()=>{error.value='';try{await login(credentials.email,credentials.password);token.value=localStorage.getItem('basga_token')}catch(e){error.value=e.message}}
const save=async()=>{error.value='';try{await saveRemotePortfolio();saved.value=true;setTimeout(()=>saved.value=false,2500)}catch(e){error.value=e.message}}
const logout=()=>{localStorage.removeItem('basga_token');token.value=''}
const slugify=v=>v.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')
const addProject=()=>projects.push({slug:'project-baru',title:'Proyek baru',category:'Website',image:'',description:'Deskripsi proyek.',long:'Detail proyek.',tech:['Vue.js']})
const addSkill=()=>skills.push(['fa-solid fa-code','Skill baru',70])
const addService=()=>services.push(['fa-solid fa-star','Layanan baru','Deskripsi layanan.'])
const activeProjects=computed(()=>projects)
</script>
<template><main v-if="!token" class="admin-login"><div class="login-card"><RouterLink to="/" class="text-link">← Kembali ke website</RouterLink><p class="eyebrow">BASGA ADMIN</p><h1>Masuk ke <em>dashboard.</em></h1><form @submit.prevent="signIn"><label>Email<input v-model.trim="credentials.email" type="email" required/></label><label>Password<input v-model="credentials.password" type="password" required/></label><p v-if="error" class="form-error">{{error}}</p><button class="button primary">Masuk</button></form></div></main><main v-else class="admin-page"><aside class="admin-sidebar"><RouterLink to="/" class="brand">BASGA</RouterLink><div><small>SUPABASE CMS</small><h2>Admin Panel</h2></div><nav class="admin-nav"><button v-for="[id,label] in sections" :class="{active:section===id}" @click="section=id">{{label}}</button></nav><button class="logout" @click="logout">Keluar</button></aside><section class="admin-content"><header><div><p class="eyebrow">KONTEN WEBSITE</p><h1>{{sections.find(x=>x[0]===section)[1]}}</h1></div><button class="button primary" @click="save">Simpan ke website</button></header><p v-if="saved" class="admin-success">✓ Tersimpan di Supabase.</p><p v-if="error" class="form-error">{{error}}</p><div v-show="section==='profile'" class="admin-card"><div class="form-grid"><label>Nama<input v-model="profile.name"/></label><label>Profesi<input v-model="profile.role"/></label><label class="full">Deskripsi<textarea v-model="profile.bio" rows="3"/></label><label class="full">Tentang<textarea v-model="profile.about" rows="4"/></label><label>Email<input v-model="profile.email"/></label><label>WhatsApp<input v-model="profile.whatsapp"/></label><label class="full">URL foto<input v-model="profile.image"/></label></div></div><div v-show="section==='projects'" class="admin-stack"><article v-for="(p,i) in activeProjects" :key="i" class="admin-card"><button class="delete" @click="projects.splice(i,1)">Hapus</button><div class="form-grid"><label>Nama<input v-model="p.title" @input="p.slug=slugify(p.title)"/></label><label>Kategori<input v-model="p.category"/></label><label class="full">Gambar<input v-model="p.image"/></label><label class="full">Deskripsi<textarea v-model="p.description"/></label></div></article><button class="add-row" @click="addProject">+ Tambah proyek</button></div><div v-show="section==='skills'" class="admin-stack"><article v-for="(s,i) in skills" :key="i" class="admin-card compact-row"><input v-model="s[1]"/><input v-model.number="s[2]" type="number"/><button class="delete" @click="skills.splice(i,1)">Hapus</button></article><button class="add-row" @click="addSkill">+ Tambah skill</button></div><div v-show="section==='services'" class="admin-stack"><article v-for="(s,i) in services" :key="i" class="admin-card"><button class="delete" @click="services.splice(i,1)">Hapus</button><div class="form-grid"><label>Nama<input v-model="s[1]"/></label><label class="full">Deskripsi<textarea v-model="s[2]"/></label></div></article><button class="add-row" @click="addService">+ Tambah layanan</button></div></section></main></template>